46	// https://github.com/kubernetes-sigs/structured-merge-diff
47	// https://docs.aws.amazon.com/eks/latest/userguide/kubernetes-field-management.html
48	// see also: https://kubernetes.slack.com/archives/C0123CNN8F3/p1686141087220719
49	public class SSABasedGenericKubernetesResourceMatcher<R extends HasMetadata> {
