78	  @SuppressWarnings("unchecked")
79	  public boolean matches(R actual, R desired, Context<?> context) {
80	    var optionalManagedFieldsEntry = checkIfFieldManagerExists(actual,
81	        context.getControllerConfiguration().fieldManager());
82	    // If no field is managed by our controller, that means the controller hasn't touched the
83	    // resource yet and the resource probably doesn't match the desired state. Not matching here
84	    // means that the resource will need to be updated and since this will be done using SSA, the
85	    // fields our controller cares about will become managed by it
86	    if (optionalManagedFieldsEntry.isEmpty()) {
87	      return false;
88	    }
89	
90	    var managedFieldsEntry = optionalManagedFieldsEntry.orElseThrow();
91	
92	    var objectMapper = context.getClient().getKubernetesSerialization();
93	
94	    var actualMap = objectMapper.convertValue(actual, Map.class);
95	
96	    sanitizeState(actual, desired, actualMap);
97	
98	    var desiredMap = objectMapper.convertValue(desired, Map.class);
99	    if (LoggingUtils.isNotSensitiveResource(desired)) {
100	      log.trace("Original actual: \n {} \n original desired: \n {} ", actual, desiredMap);
101	    }
102	
103	    var prunedActual = new HashMap<String, Object>(actualMap.size());
104	    keepOnlyManagedFields(prunedActual, actualMap,
105	        managedFieldsEntry.getFieldsV1().getAdditionalProperties(),
106	        objectMapper);
107	
108	    removeIrrelevantValues(desiredMap);
109	
110	    var matches = prunedActual.equals(desiredMap);
111	
112	    if (!matches && log.isDebugEnabled() && LoggingUtils.isNotSensitiveResource(desired)) {
113	      var diff = getDiff(prunedActual, desiredMap, objectMapper);
114	      log.debug(
115	          "Diff between actual and desired state for resource: {} with name: {} in namespace: {} is: \n{}",
116	          actual.getKind(), actual.getMetadata().getName(), actual.getMetadata().getNamespace(),
117	          diff);
118	    }
119	
120	    return matches;
121	  }
