public class ResourceRequirementsSanitizer {

  private static final String SPEC_KEY = "spec";
  private static final String TEMPLATE_KEY = "template";
  private static final String CONTAINERS_KEY = "containers";
  private static final String INIT_CONTAINERS_KEY = "initContainers";
  private static final String RESOURCES_KEY = "resources";
  private static final String REQUESTS_KEY = "requests";
  private static final String LIMITS_KEY = "limits";

  private ResourceRequirementsSanitizer() {}

  public static void sanitizeResourceRequirements(final Map<String, Object> actualMap,
      final PodTemplateSpec actualTemplate, final PodTemplateSpec desiredTemplate) {
    if (actualTemplate == null || desiredTemplate == null) {
