        desiredTemplate.getSpec().getInitContainers(), INIT_CONTAINERS_KEY);
  }

  private static void sanitizeResourceRequirements(final Map<String, Object> actualMap,
      final List<Container> actualContainers, final List<Container> desiredContainers,
      final String containerPath) {
    // the containers could be null, e.g. no init containers
    if (actualContainers == null || desiredContainers == null
        || actualContainers.size() != desiredContainers.size()) {
      return;
    }
    for (int containerIndex = 0; containerIndex < actualContainers.size(); containerIndex++) {
